178: interface RenderedOutput {
179:   summary: string;
180:   lines: string[];
181:   hiddenCount: number;
182:   /**
183:    * Optional per-line error flag, index-aligned with `lines`. Set only by the
184:    * Bash branch (A1): the `STDERR:` section and `Exit code:` / `Killed by
185:    * signal:` status lines render in the error color without altering the text.
186:    */
187:   errorLines?: boolean[];
188: }
189: 
190: /**
191:  * Strip <system-reminder>…</system-reminder> blocks from tool output before
192:  * rendering. The InvestigationGuard prepends these to nudge the LLM mid-loop;
193:  * they're context for the model, not status for the user.
194:  */
195: function stripSystemReminders(content: string): string {
196:   return content.replace(/<system-reminder>[\s\S]*?<\/system-reminder>\s*/g, "");
197: }
198: 
199: function renderToolOutput(toolName: string, content: string, expanded: boolean): RenderedOutput {
200:   content = stripSystemReminders(content);
201:   const rawLines = content.split("\n");
202:   const totalLines = rawLines.length;
203: 
204:   switch (toolName) {
205:     case "Read": {
206:       // Read: show summary only (no preview lines)
207:       return {
208:         summary: `${totalLines} lines, ${formatBytes(content.length)}`,
209:         lines: [],
210:         hiddenCount: 0,
211:       };
212:     }
213: 
214:     case "Write": {
215:       // Write returns the raw file content. Show only the first-line summary
216:       // when collapsed; the rest of the body isn't useful inline — the user
217:       // can re-read the file if they need it.
218:       const summary = singleLine(rawLines[0] ?? "").slice(0, 80);
219:       return { summary, lines: [], hiddenCount: 0 };
220:     }
221: 
222:     case "Edit": {
223:       // Edit tool returns "Successfully edited <file>\n<diff>" where the
224:       // diff is a `  - …` / `  + …` block (see edit.ts generateCompactDiff).
225:       // Show the summary collapsed; expose the full diff in expanded /
226:       // transcript mode so additions/removals get DiffColoredLine treatment.
227:       const [summaryLine, ...rest] = rawLines;
228:       const summary = singleLine(summaryLine ?? "").slice(0, 80);
229:       const diffLines = rest.filter((l) => l.length > 0);
230:       if (expanded) {
231:         return { summary, lines: diffLines, hiddenCount: 0 };
232:       }
233:       if (diffLines.length === 0) {
234:         return { summary, lines: [], hiddenCount: 0 };
235:       }
236:       const previewCount = Math.min(diffLines.length, COLLAPSED_LINES);
237:       return {
238:         summary,
239:         lines: diffLines.slice(0, previewCount),
240:         hiddenCount: Math.max(0, diffLines.length - previewCount),
241:       };
242:     }
243: 
244:     case "Glob": {
245:       // Strip the "N files matched:" header glob.ts emits so the count is accurate.
246:       const files = rawLines
247:         .filter((l) => l.trim())
248:         .filter((l) => !/^\d+\s+files?\s+matched/i.test(l));
249:       const count = files.length;
250:       if (expanded) {
251:         return { summary: `${count} files`, lines: files, hiddenCount: 0 };
252:       }
253:       // Few results: show them inline — making the user ctrl+o for a 2-file
254:       // match was a regression. Many results: summary + first N + "+M lines".
255:       if (count <= COLLAPSED_LINES) {
256:         return { summary: `${count} files`, lines: files, hiddenCount: 0 };
257:       }
258:       return {
259:         summary: `${count} files`,
260:         lines: files.slice(0, COLLAPSED_LINES),
261:         hiddenCount: count - COLLAPSED_LINES,
262:       };
263:     }

