138: function compactSummary(toolName: string, content: string): string {
139:   const lines = content.split("\n");
140:   const total = lines.length;
141: 
142:   switch (toolName) {
143:     case "Read":
144:       return `${total} lines, ${formatBytes(content.length)}`;
145:     case "Glob":
146:       return `${lines.filter((l) => l.trim()).length} files`;
147:     case "Grep":
148:       return `${lines.filter((l) => l.trim()).length} matches`;
149:     case "Write":
150:     case "Edit":
151:       return truncate(singleLine(content), 60);
152:     case "Bash": {
153:       if (total <= 1) return truncate(singleLine(content), 80);
154:       const preview = truncate(lines[0], 60);
155:       return `${preview} (+${total - 1} lines)`;
156:     }
157:     case "view_image":
158:       return extractViewImagePath(content) ?? truncate(content, 80);
159:     default:
160:       if (total <= 1) return truncate(content, 80);
161:       return `${truncate(lines[0], 60)} (+${total - 1} lines)`;
162:   }
163: }
